#!/bin/bash
# Copyright: Ankitects Pty Ltd and contributors
# License: GNU AGPL, version 3 or later; http://www.gnu.org/licenses/agpl.html
#
# Generates the Swift code the app uses to talk to the Rust backend over
# protobuf, into out/ios/generated/ (not checked in):
#
# - out/ios/generated/proto/anki/*.pb.swift: the message types, generated by
#   protoc-gen-swift (swift-protobuf 1.28.x; `brew install swift-protobuf`).
# - out/ios/generated/BackendServices.swift: method indices and typed
#   wrappers, written by rslib/proto/build.rs (rslib/proto/swift.rs) whenever
#   the anki_proto crate is built, eg by ios/build-rust.sh. If it is missing,
#   it is generated here with `cargo build -p anki_proto`.
#
# Environment:
#   PROTOC            protoc binary (default: out/extracted/protoc/bin/protoc,
#                     the one .cargo/config.toml uses, else protoc on PATH)
#   PROTOC_GEN_SWIFT  protoc-gen-swift binary (default: found on PATH)

set -euo pipefail

cd "$(dirname "$0")/.."
ROOT=$(pwd)
OUT="$ROOT/out/ios/generated"

if [ -z "${PROTOC:-}" ]; then
    if [ -x "$ROOT/out/extracted/protoc/bin/protoc" ]; then
        PROTOC="$ROOT/out/extracted/protoc/bin/protoc"
    else
        PROTOC=$(command -v protoc || true)
    fi
fi
if [ -z "$PROTOC" ] || [ ! -x "$PROTOC" ]; then
    echo "protoc not found: run ios/build-rust.sh first, or set PROTOC" >&2
    exit 1
fi

PROTOC_GEN_SWIFT=${PROTOC_GEN_SWIFT:-$(command -v protoc-gen-swift || true)}
if [ -z "$PROTOC_GEN_SWIFT" ] || [ ! -x "$PROTOC_GEN_SWIFT" ]; then
    echo "protoc-gen-swift not found: brew install swift-protobuf, or set PROTOC_GEN_SWIFT" >&2
    exit 1
fi

rm -rf "$OUT/proto"
mkdir -p "$OUT/proto"
# The default FileNaming=FullPath keeps the anki/ directory, so files with
# the same name in different packages cannot clash. Types get the package
# prefix (anki.decks.Deck -> Anki_Decks_Deck), which BackendServices.swift
# relies on.
"$PROTOC" \
    --plugin=protoc-gen-swift="$PROTOC_GEN_SWIFT" \
    --proto_path="$ROOT/proto" \
    --swift_opt=Visibility=Internal \
    --swift_out="$OUT/proto" \
    "$ROOT"/proto/anki/*.proto
echo "Generated $(find "$OUT/proto" -name '*.pb.swift' | wc -l | tr -d ' ') files in $OUT/proto"

if [ ! -f "$OUT/BackendServices.swift" ]; then
    # build.rs only reruns when its inputs change, so make sure it does
    touch "$ROOT/rslib/proto/swift.rs"
    cargo build -p anki_proto
fi
if [ ! -f "$OUT/BackendServices.swift" ]; then
    echo "$OUT/BackendServices.swift was not generated" >&2
    exit 1
fi
